    "id": "announcement_v360_stitch_promax",
    "channel_id": "announcements",
    "channelId": "announcements",
    "sender_id": "4fecc8e6-2d27-4560-886b-ec88edeaa48a",
    "author_id": "4fecc8e6-2d27-4560-886b-ec88edeaa48a",
