export const LIVE_EDGE_MESSAGES = [];

export function getFallbackUser(ident) {
  if (!ident) return null;
  const clean = ident.trim().toLowerCase().replace(/^@/, "");
  return CANONICAL_USERS.find(u => 
    u.id === ident || 
    u.username.toLowerCase() === clean || 
    (u.email && u.email.toLowerCase() === clean) ||
    (clean === "chinnu" && u.username.toLowerCase() === "chinnu14754x")
  ) || null;
}

export function getFallbackFriends(myUsername) {
  const cleanMy = (myUsername || "").trim().toLowerCase().replace(/^@/, "");
  const me = getFallbackUser(cleanMy) || { id: "usr_3b394606", username: "chinnu14754x", display_name: "chinnu" };
  
  const userMap = new Map();
  for (const u of CANONICAL_USERS) {
    userMap.set(u.id, u);
    userMap.set(u.username.toLowerCase(), u);
  }

  const acceptedFriends = [];
  const seenIds = new Set();

  for (const f of CANONICAL_FRIENDSHIPS) {
    if (f.status !== "accepted") continue;
    let friendId = null;
    if (f.user_id === me.id || f.user_id === me.username) {
      friendId = f.friend_id;
    } else if (f.friend_id === me.id || f.friend_id === me.username) {
      friendId = f.user_id;
    }
    if (friendId && friendId !== me.id && !seenIds.has(friendId)) {
      seenIds.add(friendId);
      const friendUser = userMap.get(friendId) || userMap.get(String(friendId).toLowerCase());
      if (friendUser) {
        acceptedFriends.push(friendUser);
      }
    }
  }

  if (acceptedFriends.length === 0 && (cleanMy === "chinnu14754x" || cleanMy === "chinnu")) {
    const coreFriendUsernames = ["divya1736", "meghana", "devi", "siddhartha", "srinu", "test1"];
    for (const uName of coreFriendUsernames) {
      const u = userMap.get(uName);
      if (u && !seenIds.has(u.id)) {
        seenIds.add(u.id);
        acceptedFriends.push(u);
      }
    }
  }

  const allMsgs = [...CANONICAL_MESSAGES, ...LIVE_EDGE_MESSAGES];

  return acceptedFriends.map(f => {
    const uName = f.username;
    const dName = f.display_name || uName;
    const av = f.avatar_url || "👾";
    const ban = f.banner_url || "";

    const pairSorted = [me.username.toLowerCase(), uName.toLowerCase()].sort();
    const chName1 = "dm-" + pairSorted.join("-");
    const chName2 = "dm_" + pairSorted.join("_");

    const dmMessages = allMsgs.filter(m => m.channel_id === chName1 || m.channel_id === chName2);
    let lastMsg = null;
    if (dmMessages.length > 0) {
      lastMsg = dmMessages[dmMessages.length - 1];
    }

    return {
      id: f.id,
      user_id: me.id,
      friend_id: f.id,
      username: uName,
      friend_username: uName,
      display_name: dName,
      friend_display_name: dName,
      nickname: dName,
      avatar: av,
      avatar_url: av,
      friend_avatar_url: av,
      banner_url: ban,
      friend_banner_url: ban,
      status: "online",
      is_online: true,
      is_stealth: false,
      bio: f.bio || "Connecto friend",
      last_message: lastMsg ? lastMsg.content : null,
      last_timestamp: lastMsg ? lastMsg.created_at : null,
      last_message_timestamp: lastMsg ? new Date(lastMsg.created_at.endsWith("Z") ? lastMsg.created_at : lastMsg.created_at + "Z").getTime() : 0,
      unread_count: 0
    };
  });
}

export function getFallbackMessages(channelInput) {
  if (!channelInput) return [];
  const cleanCh = channelInput.trim().toLowerCase();
  
  let normalized = cleanCh;
  if (cleanCh.startsWith("dm-") || cleanCh.startsWith("dm_")) {
    const parts = cleanCh.replace(/^dm[-_]/, "").split(/[-_]/);
    if (parts.length >= 2) {
      const sorted = [parts[0].trim(), parts[1].trim()].sort();
      normalized = "dm-" + sorted.join("-");
    }
  }

  const allMsgs = [...CANONICAL_MESSAGES, ...LIVE_EDGE_MESSAGES];
  return allMsgs.filter(m => {
    const mCh = (m.channel_id || "").toLowerCase();
    if (mCh === cleanCh || mCh === normalized) return true;
    if (cleanCh.startsWith("dm-") || cleanCh.startsWith("dm_")) {
      const parts = cleanCh.replace(/^dm[-_]/, "").split(/[-_]/);
      if (parts.length >= 2) {
        return mCh.includes(parts[0]) && mCh.includes(parts[1]);
      }
    }
    return false;
  });
}
